"""Generate SYNTHETIC annotations so the alignment pipeline is demonstrable offline.

**These are not human judgements.** They are generated by a deterministic model of an
imperfect rater: it mostly agrees with the trace evidence, disagrees more on subtle
categories, and two simulated annotators disagree with each other at a realistic rate.

Every record produced here carries ``metadata["synthetic"] = True``, and the dashboard
and reports surface that prominently. Agreement statistics computed over these labels
describe *this simulator*, not human agreement, and must never be cited as evidence that
the automated evaluators match human raters. Real numbers require the annotation UI and
real people:

    evalforge annotate

The script exists because the alternative — shipping an alignment page that is blank
until someone hand-labels 60 sessions — would leave a whole subsystem unexercised and
untestable.

Usage::

    python scripts/simulate_annotations.py --run-id <RUN_ID> --sessions 60
    python scripts/simulate_annotations.py --all-runs
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))

from evalforge.config import load_config
from evalforge.ids import stable_id
from evalforge.rng import chance, seeded_random
from evalforge.schemas.annotation import DimensionRating, HumanAnnotation
from evalforge.schemas.common import Dimension, FailureCategory, Severity
from evalforge.schemas.evaluation import SessionSummary
from evalforge.storage.store import RunStore

RATED_DIMENSIONS = (
    Dimension.TASK_COMPLETION,
    Dimension.CONTEXT_RETENTION,
    Dimension.INSTRUCTION_ADHERENCE,
    Dimension.RECOVERY_QUALITY,
)

#: How often each simulated annotator diverges from the automated verdict. Different
#: rates give the two "annotators" a realistic human-human disagreement level, which is
#: what makes the human-human ceiling non-trivial.
ANNOTATOR_NOISE = {"annotator_a": 0.10, "annotator_b": 0.16}

#: Categories a human rater is modelled as finding harder to spot, so agreement is
#: lower there. Goal drift is the canonical example: each individual turn looks helpful.
SUBTLE_CATEGORIES = {"goal_drift", "cascading_errors", "long_session_stress"}


def _rating_for(
    summary: SessionSummary, dimension: Dimension, rng_seed: tuple[object, ...], noise: float
) -> int:
    """Map an automated dimension score onto a 1..5 rubric rating, with rater noise."""
    score = {
        Dimension.TASK_COMPLETION: summary.task_completion_score,
        Dimension.CONTEXT_RETENTION: summary.context_retention_score,
        Dimension.INSTRUCTION_ADHERENCE: summary.instruction_adherence_score,
        Dimension.RECOVERY_QUALITY: summary.recovery_score,
    }[dimension]

    base = 1 + round(score * 4)
    rng = seeded_random(*rng_seed, dimension.value)
    if rng.random() < noise:
        base += rng.choice([-1, 1])
    return max(1, min(5, base))


def simulate_for_run(
    store: RunStore,
    run_id: str,
    session_limit: int,
    annotators: tuple[str, ...] = ("annotator_a", "annotator_b"),
    seed: int = 42,
) -> int:
    """Generate synthetic annotations for one run.

    Returns:
        Number of annotations written.
    """
    sessions = store.get_sessions(run_id)
    if not sessions:
        print(f"  run {run_id}: no sessions, skipping")
        return 0

    # Stratify by category so the subgroup analyses have coverage rather than whatever
    # the worst-scoring sessions happened to be.
    by_category: dict[str, list[SessionSummary]] = {}
    for item in sessions:
        by_category.setdefault(item.scenario_category, []).append(item)

    selected: list[SessionSummary] = []
    index = 0
    while len(selected) < min(session_limit, len(sessions)):
        added = False
        for category in sorted(by_category):
            pool = by_category[category]
            if index < len(pool) and len(selected) < session_limit:
                selected.append(pool[index])
                added = True
        if not added:
            break
        index += 1

    written = 0
    for summary in selected:
        subtle = summary.scenario_category in SUBTLE_CATEGORIES
        for annotator in annotators:
            noise = ANNOTATOR_NOISE.get(annotator, 0.12)
            if subtle:
                noise += 0.12

            coordinates = (seed, run_id, summary.session_id, annotator)
            flips = chance(noise, *coordinates, "verdict")
            overall_pass = (not summary.passed) if flips else summary.passed

            categories: list[FailureCategory] = []
            if not overall_pass:
                for name in summary.failure_categories[:3]:
                    try:
                        categories.append(FailureCategory(name))
                    except ValueError:
                        continue

            severity = Severity.INFO
            if summary.critical_failures and not flips:
                severity = Severity.CRITICAL
            elif not overall_pass:
                severity = Severity.MAJOR

            rng = seeded_random(*coordinates, "duration")
            annotation = HumanAnnotation(
                annotation_id=stable_id("annotation", run_id, summary.session_id, annotator),
                run_id=run_id,
                session_id=summary.session_id,
                scenario_id=summary.scenario_id,
                annotator_id=annotator,
                ratings=[
                    DimensionRating(
                        dimension=dimension,
                        rating=_rating_for(summary, dimension, coordinates, noise),
                    )
                    for dimension in RATED_DIMENSIONS
                ],
                overall_pass=overall_pass,
                failure_categories=categories,
                severity=severity,
                comments=(
                    "SYNTHETIC annotation generated by scripts/simulate_annotations.py. "
                    "Not a human judgement."
                ),
                blind=True,
                duration_seconds=round(rng.uniform(90, 420), 1),
                metadata={
                    "synthetic": True,
                    "generator": "scripts/simulate_annotations.py",
                    "noise_rate": round(noise, 4),
                    "warning": (
                        "Simulated rater. Agreement statistics over these labels describe "
                        "the simulator, not human agreement."
                    ),
                },
            )
            store.save_annotation(annotation)
            written += 1

    print(f"  run {run_id}: {written} synthetic annotations over {len(selected)} sessions")
    return written


def main() -> int:
    """Entry point."""
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("--run-id", help="Run to annotate. Omit with --all-runs.")
    parser.add_argument("--all-runs", action="store_true", help="Annotate every stored run.")
    parser.add_argument("--sessions", type=int, default=60, help="Sessions per run.")
    parser.add_argument("--seed", type=int, default=42, help="Seed for the simulated raters.")
    args = parser.parse_args()

    if not args.run_id and not args.all_runs:
        parser.error("Pass --run-id <RUN_ID> or --all-runs.")

    config = load_config()
    store = RunStore(config.paths.runs, config.storage.database_name)

    print("=" * 78)
    print("GENERATING SYNTHETIC ANNOTATIONS — THESE ARE NOT HUMAN JUDGEMENTS")
    print("Agreement statistics computed over them describe this simulator only.")
    print("For real numbers, collect annotations with: evalforge annotate")
    print("=" * 78)

    run_ids = [item.run_id for item in store.list_runs()] if args.all_runs else [args.run_id]
    total = sum(
        simulate_for_run(store, run_id, args.sessions, seed=args.seed) for run_id in run_ids
    )

    print(f"\nWrote {total} synthetic annotations across {len(run_ids)} run(s).")
    print("View the analysis: evalforge dashboard  →  Evaluator alignment")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
